"""Premium proposal pages, with property-specific products and sourced conditions."""
import json,re
from offer_details import SCENARIOS,PROMOS,TERMS,LOYALTY,LOYALTY_TERMS,FAMILY_ROOMS

def config(p,g):
 i=p['id'];hotels=g['HOTELS']
 if i in SCENARIOS:return dict(SCENARIOS[i])
 if i in PROMOS:
  title,subtitle,hid,kind=PROMOS[i];ids=[hid] if hid else list(hotels)
  if kind=='four':ids=['lubyansky','tagansky']
  if kind=='archive':ids=['tverskaya','lubyansky']
  rooms=FAMILY_ROOMS if kind=='archive' else [next(r['id'] for r in g['PAGES'].values() if r['template']=='room' and r['id'].startswith(h+'_') and 'мансард' not in r['h1'].lower()) for h in ids]
  if len(rooms)==1:rooms=[r['id'] for r in g['PAGES'].values() if r['template']=='room' and r['id'].startswith(ids[0]+'_')][:2]
  return dict(title=title,subtitle=subtitle,intro='Выберите даты и познакомьтесь с условиями предложения до оформления.',asset=rooms[0],hotels=ids,rooms=rooms,cta='Посмотреть категории',rooms_title='Рассмотрите номера для поездки',rooms_intro='Наличие и применение предложения проверяются в официальном тарифе.',conditions_title='Условия предложения',conditions=TERMS[kind],band_title='Важны детали вашей поездки?',band_text='Согласуйте особенности размещения и применение предложения с отелем до оплаты.',map_title='Выберите расположение',kind=kind)
 if i in LOYALTY:
  title,subtitle,intro=LOYALTY[i]
  return dict(title=title,subtitle=subtitle,intro=intro,asset='tverskaya_room_6',hotels=list(hotels),rooms=[],cta='Подобрать номер',conditions_title='Как пользоваться программой',conditions=LOYALTY_TERMS[i],band_title='Проверьте условия вашей карты',band_text='Уровень участия и преимущества нужно подтвердить до оплаты. Итоговая стоимость зависит от выбранного тарифа.',map_title='Отели для следующей поездки')
 return dict(title='У каждой поездки —<br>свой повод',subtitle='Предложения отелей Туррис',intro='Семья, работа или несколько недель в Москве. Выберите подходящий сценарий.',asset='lubyansky_room_3',hotels=list(hotels),rooms=[],cta='Подобрать номер',conditions_title='Выбирайте по условиям',conditions=[('Даты и гости','Сравнивайте предложения на один период и одинаковый состав гостей.'),('Что включено','Проверьте питание, спальные места, предоплату и отмену.'),('До оформления','Скидки и наличие подтверждаются в официальном тарифе. В прототипе нет расчёта стоимости.')],band_title='Поможем подобрать размещение',band_text='Расскажите о составе гостей, датах и пожеланиях. Проверим, какие детали нужно согласовать с отелем.',map_title='Четыре адреса в Москве')

def header(p,g):
 a,icon=g['a'],g['icon'];label='Семейные номера' if p['id']=='family' else 'Предложения'
 return '<a class="skip" href="#main">Перейти к содержанию</a><header class="header of-header"><div class="wrap header-inner"><div class="brand-block">'+a('home','TURRIS<span>ONLINE</span><i></i>','logo','aria-label="Туррис — главная"')+'</div><nav class="nav" id="main-nav" aria-label="Навигация предложения">'+a('hotels','Отели')+'<a href="#options">'+label+'</a><a href="#conditions">Условия</a><a href="#map">На карте</a>'+a('offers','Все предложения','of-all-offers')+'</nav><a class="header-phone" href="tel:88005054455" aria-label="Позвонить 8 800 505 44 55">'+icon('phone')+'<span>8 800 505 44 55</span></a><a class="btn header-booking" href="#offer-search">'+('Запросить расчёт' if p['id']=='groups' else 'Подобрать номер')+' '+icon('arrow')+'</a><button class="demo-badge" data-demo-info>ДЕМО</button><button class="menu-button" aria-label="Открыть меню" aria-expanded="false" aria-controls="main-nav">'+icon('menu')+'</button></div></header>'

def footer(g):
 a,icon=g['a'],g['icon']
 return '<footer class="footer of-footer"><div class="wrap"><div class="of-footer-grid"><div>'+a('home','TURRIS<span>ONLINE</span><i></i>','logo')+'<p>Отели в Москве</p></div><div><h3>Для гостей</h3>'+a('offers','Все предложения')+a('hotels','Номера')+a('help','Условия проживания')+a('booking','Бронирование')+'</div><div><h3>Помощь</h3><a href="tel:88005054455">'+icon('phone')+'8 800 505 44 55</a>'+a('contacts','Контакты')+'</div></div><div class="footer-bottom"><span>© 2026 Туррис · Демонстрационный прототип</span>'+a('privacy','Политика конфиденциальности')+'</div></div></footer>'

def render(p,g):
 a,e,image,icon,url,ext=[g[k] for k in ('a','e','image','icon','url','ext')];i=p['id'];d=config(p,g);hotels=g['HOTELS'];is_family=i=='family';is_group=i=='groups'
 caption=d.get('caption') or hotels[next(h for h in hotels if d['asset'].startswith(h))]['name']+' · '+g['room_name'](g['PAGES'][d['asset']])
 hero='<section class="of-hero"><div class="of-hero-copy"><div class="eyebrow">Туррис · Москва</div><h1>'+d['title']+'</h1><h2>'+d['subtitle']+'</h2><p>'+d['intro']+'</p><a href="#'+('offer-search' if is_group else 'options')+'" class="text-link">'+('Запросить расчёт' if is_group else 'Сравнить варианты')+' ↓</a></div><figure class="of-hero-photo">'+image(d['asset'],caption,eager=True,sizes='(max-width:640px) calc(100vw - 32px), (max-width:1000px) 58vw, 710px')+'<figcaption>'+caption+'</figcaption></figure></section>'
 preset=d['hotels'][0] if len(d['hotels'])==1 else ''
 form=g['booking_form'](preset)
 form=re.sub(r'<option value="([^"]+)"[^>]*>.*?</option>',lambda m:m.group(0) if m.group(1) in d['hotels'] else '',form)
 if preset:form=form.replace('<option value="">Любой из четырёх</option>','')
 form=form.replace('Любой из четырёх','Все подходящие отели')
 scenario='family' if is_family or d.get('kind')=='archive' else 'offer_four' if d.get('kind')=='four' else ''
 form=form.replace('data-booking ', 'data-booking data-offer-form data-scenario="'+scenario+'" ')
 if i=='longstay':form=form.replace('data-offer-form','data-offer-form data-min-nights="21"')
 if is_family:
  form=form.replace('<label class="field">Гости', '<label class="field of-hidden-guests">Гости')
  controls=''.join('<div class="of-inline-counter">'+icon(ic)+'<span>'+name+'</span><div><button type="button" data-family-count="'+kind+'" data-delta="-1" aria-label="Уменьшить: '+name+'">−</button><output data-family-value="'+kind+'">'+str(n)+'</output><button type="button" data-family-count="'+kind+'" data-delta="1" aria-label="Добавить: '+name+'">+</button></div></div>' for kind,name,ic,n in [('adults','Взрослые','guest',2),('children','Дети','guest',0)])
  form=form.replace('<input type="hidden" name="checkin">',controls+'<div class="of-child-ages" data-family-ages></div><input type="hidden" name="checkin">')
 form=form.replace('Показать номера и цены',d['cta'])
 panel='<section class="of-search '+('of-family-search' if is_family else '')+'" id="offer-search" aria-label="Подбор размещения">'+form+'<div class="of-search-note"><span>'+('Возраст детей — на дату заезда.' if is_family else 'Условия проверяются на весь период поездки.')+'</span><span>Наличие и стоимость — на официальном сайте отеля.</span></div><p class="of-selection" data-offer-selection aria-live="polite"></p><button type="button" class="text-link of-clear" data-offer-clear hidden>Сравнить все варианты</button></section>'
 if is_group:panel='<section id="offer-search" class="of-group-search">'+g['lead_form']('groups')+'</section>'
 nav='<nav class="of-tabs" aria-label="На странице">'+''.join('<a href="#'+k+'">'+label+'</a>' for k,label in [('options','Номера' if d['rooms'] else 'Варианты'),('conditions','Условия для детей' if is_family else 'Условия'),('map','Расположение'),('questions','Вопросы')])+'</nav>'
 def room_card(rid):
  r=g['PAGES'][rid];hid=g['room_hotel'](r);name=g['room_name'](r);beds,detail=g['room_facts'](r)
  names={'lubyansky_room_3':'Deluxe Suite Double','lubyansky_room_1':'Deluxe Suite Twin','lubyansky_room_6':'Duplex Suite'};name=names.get(rid,name)
  fact='До 4 мест' if rid in FAMILY_ROOMS[:3] else 'Два уровня' if rid=='lubyansky_room_6' else 'Мансардный потолок' if 'мансард' in r['h1'].lower() else 'Категория на ваши даты'
  warning='Внутри номера есть лестница' if rid=='lubyansky_room_6' else 'В здании нет лифта' if hid=='tagansky' else ''
  if rid=='tverskaya_room_1':beds='Спальня с большой кроватью и гостиная с диваном.'
  return '<article class="of-room"><a class="of-room-photo" href="'+url(rid)+'">'+image(rid,name+', '+hotels[hid]['full'],sizes='(max-width:640px) calc(100vw - 32px), 560px')+'</a><div class="of-room-body"><div class="eyebrow">'+hotels[hid]['name']+'</div><h3>'+name+'</h3><p>'+icon('guest')+fact+'</p><p>'+icon('document')+beds+'</p>'+('<p class="of-room-warning">'+icon('pin')+warning+'</p>' if warning else '')+'<div class="of-room-actions"><a class="btn secondary" href="'+url('booking')+'?hotel='+hid+'&room='+rid+'" data-offer-room="'+rid+'" data-offer-hotel="'+hid+'" data-offer-room-name="'+e(name)+'">Проверить на мои даты '+icon('arrow')+'</a>'+a(rid,'Фото и описание ↗','text-link')+'</div></div></article>'
 def option_card(dest,title,text,asset,category='trip'):
  return '<article class="of-option" data-offer-category="'+category+'"><a class="of-option-photo" href="'+url(dest)+'">'+image(asset,title,sizes='(max-width:640px) calc(100vw - 32px), 560px')+'</a><div><h3>'+a(dest,title)+'</h3><p>'+text+'</p>'+a(dest,'Подробнее '+icon('arrow'),'text-link')+'</div></article>'
 if d['rooms']:
  options='<section class="of-section" id="options"><h2>'+d['rooms_title']+'</h2><p class="of-sub">'+d['rooms_intro']+'</p><div class="of-rooms">'+''.join(room_card(r) for r in d['rooms'])+'</div><p class="of-caption">Допустимый состав гостей и стоимость зависят от категории и тарифа.</p></section>'
 elif i in LOYALTY:
  options='<section class="of-section" id="options"><h2>Выберите вашу программу</h2><p class="of-sub">Уточните участие и преимущества до бронирования.</p><div class="of-programs">'+''.join('<article><span class="of-program-number">0'+str(n)+'</span><div class="eyebrow">Программа лояльности</div><h3>'+LOYALTY[k][1]+'</h3><p>'+LOYALTY[k][2]+'</p>'+a(k,'Посмотреть условия '+icon('arrow'),'text-link')+'</article>' for n,k in enumerate(['loyalty_standard','loyalty_platinum','loyalty_aeroflot'],1) if k!=i)+'</div></section>'
 elif is_group:
  options='<section class="of-section" id="options"><h2>Четыре адреса для вашей группы</h2><p class="of-sub">Сравните расположение. Наличие комнат на группу подтвердит отель.</p><div class="of-rooms">'+''.join(option_card(h,hotels[h]['name'],hotels[h]['location']+'. '+hotels[h]['notice'],h) for h in d['hotels'])+'</div></section>'
 else:
  options='<section class="of-section" id="options"><h2>Выберите повод приехать</h2><p class="of-sub">У каждого сценария — свой подбор и важные условия.</p><div class="of-rooms">'+''.join(option_card(k,SCENARIOS[k]['subtitle'],SCENARIOS[k]['intro'],SCENARIOS[k]['asset']) for k in ['family','longstay','business','groups'])+option_card('loyalty','Туррис-Бонус','Программы для следующих поездок и условия участия.','tverskaya_room_6')+option_card('offer_7','День рождения в Москве','Опубликованные условия праздничного предложения.','lubyansky_room_3')+'</div></section>'
  options+='<section class="of-section of-catalog"><h2>Предложения из каталога сети</h2><div class="of-filter"><label>Отель<select data-offer-filter><option value="all">Все предложения</option>'+''.join('<option value="'+h+'">'+hotels[h]['name']+'</option>' for h in hotels)+'</select></label><span data-offer-count aria-live="polite">10 предложений</span></div><div class="of-promo-grid">'+''.join('<article data-promo-hotel="'+('lubyansky tagansky' if PROMOS[k][3]=='four' else PROMOS[k][2] or 'all')+'"><div class="eyebrow">'+('Лубянский · Таганский' if PROMOS[k][3]=='four' else hotels[PROMOS[k][2]]['name'] if PROMOS[k][2] else 'Условия сети')+'</div><h3>'+a(k,PROMOS[k][1])+'</h3><p>'+('Действие акции не подтверждено.' if PROMOS[k][3]=='archive' else 'Проверьте условия и применимость на ваши даты.')+'</p>'+a(k,'Условия '+icon('arrow'),'text-link')+'</article>' for k in PROMOS)+'</div></section>'
 conditions='<section class="of-conditions" id="conditions"><h2>'+d['conditions_title']+'</h2><div>'+''.join('<article>'+icon(ic)+'<div><h3>'+title+'</h3><p>'+text+'</p></div></article>' for ic,(title,text) in zip(['guest','document','headset'],d['conditions']))+'</div>'+('<p class="of-source">'+ext('https://turris.online'+p.get('old_url',p['url']),'Условия на официальном сайте')+' · Проверено 29.10.2026</p>' if i in LOYALTY or (i in PROMOS and d.get('kind')!='archive') or i=='longstay' else '')+'</section>'
 band_dest='#company-request' if i in ['longstay','business'] else 'tel:88005054455'
 band='<aside class="of-band">'+icon('document')+'<div><h2>'+d['band_title']+'</h2><p>'+d['band_text']+'</p></div><a class="btn white" href="'+band_dest+'">'+('Запросить расчёт' if band_dest.startswith('#') else 'Уточнить условия')+' '+icon('arrow')+'</a></aside>'
 mapdata={h:dict(g['MAP']['hotels'][h],name=hotels[h]['name']) for h in d['hotels']}
 mapcards=''.join('<article><button type="button" data-map-select="'+h+'" aria-pressed="false"><b>0'+str(n)+'</b><span>'+hotels[h]['name']+'<small>'+hotels[h]['location']+'</small></span></button><p>'+icon('pin')+hotels[h]['address']+'</p>'+ext(mapdata[h]['source']+'?rtext=~'+str(mapdata[h]['lat'])+','+str(mapdata[h]['lng']),'Построить маршрут','text-link')+'<a href="#'+('offer-search' if is_group else 'options')+'" class="btn secondary" data-offer-map-hotel="'+h+'">'+('Указать в запросе' if is_group else 'Выбрать этот отель')+' '+icon('arrow')+'</a></article>' for n,h in enumerate(d['hotels'],1))
 maphtml='<section class="of-section"><h2>'+d['map_title']+'</h2><div class="hotel-map of-map" id="map" data-hotel-map data-selected="'+d['hotels'][0]+'" data-tile-url="'+g['MAP']['tile_url']+'"><div class="of-map-layout"><div class="map-stage"><div class="map-canvas" data-map-canvas role="region" aria-label="Расположение отелей предложения"></div><div class="map-toolbar"><button type="button" data-map-reset>Все адреса</button><button type="button" data-offer-map-expand aria-expanded="false" aria-label="Развернуть карту">⛶</button></div><p class="map-status" data-map-status role="status">Загружаем карту… Адреса и маршруты доступны рядом.</p></div><div class="of-map-cards">'+mapcards+'</div></div><span class="sr-only" data-map-announcement aria-live="polite"></span><script type="application/json" data-map-config>'+json.dumps(mapdata,ensure_ascii=False)+'</script></div></section>'
 qs=[('Как учитывается возраст ребёнка?','Укажите возраст каждого ребёнка на дату заезда. От него зависят условия размещения, питания и дополнительных мест.',None),('Будет ли у ребёнка отдельное спальное место?','Сравните кровати и диван в описании номера. Размещение без отдельного места не равно отдельной кровати: нужный вариант подтвердите при оформлении.',None),('Как разместиться с двумя детьми?','Рассмотрите семейный люкс Тверской, Deluxe Suite Double и Twin Лубянского. У Duplex есть внутренняя лестница. Вместимость и размещение детей уточняются для выбранного тарифа.',None),('Можно ли запросить детскую кроватку?','Да, можно передать пожелание отелю. Возможность установки, наличие и стоимость нужно подтвердить до оплаты.',None),g['FAQ'][1],('Удобно ли приехать с коляской?','Уточните вход, лифт, этаж и хранение коляски в выбранном отеле. Внутри номера Duplex Лубянского есть лестница.',None),('Какие документы нужны для заселения с ребёнком?','Подготовьте документы каждого гостя. Требования для возраста ребёнка и поездки без родителей проверьте в правилах выбранного отеля.','help'),g['FAQ'][5],g['FAQ'][0]] if is_family else [('Как проверить предложение на мои даты?','Выберите период и состав гостей. Подтвердите применение предложения, наличие категории и итоговую стоимость в официальном модуле или у отеля.',None),('Можно ли совместить несколько скидок?','Совместимость зависит от правил программы и тарифа. Не рассчитывайте на суммирование без подтверждения отеля.',None),g['FAQ'][0],g['FAQ'][1],g['FAQ'][6]]
 faq='<section class="of-section of-faq" id="questions"><div><h2>'+('Вопросы<br>родителей' if is_family else 'Ответы перед<br>поездкой')+'</h2><p>Расскажите о вашей поездке — поможем с выбором.</p><a href="tel:88005054455">'+icon('phone')+'8 800 505 44 55</a></div>'+g['faqs'](qs)+'</section>'
 bottom='<section class="of-bottom"><h2>'+('Номер для вашей<br>семьи — на ваши даты' if is_family else 'Ваша поездка —<br>ваши даты')+'</h2><a href="#offer-search" class="of-bottom-date" data-offer-dates>'+icon('calendar')+'<span data-offer-date-summary>Выберите даты</span>'+icon('chevron')+'</a><a href="#offer-search" class="of-bottom-guests" data-offer-guests>'+icon('guest')+'<span data-offer-guest-summary>Укажите гостей</span></a><a class="btn" href="#offer-search" data-offer-submit>'+('Запросить расчёт' if is_group else 'Показать номера и цены')+' '+icon('arrow')+'</a></section>'
 request='<section class="of-section of-request" id="company-request"><div><div class="eyebrow">'+('От 21 дня · Петровский' if i=='longstay' else 'Для компаний')+'</div><h2>Расскажите о вашей поездке</h2><p>Запрос помогает согласовать срок, размещение и документы. В демонстрации заявка не отправляется.</p></div>'+g['lead_form'](i)+'</section>' if i in ['longstay','business'] else ''
 return '<div class="wrap offer-page" data-offer-page="'+i+'">'+hero+panel+nav+options+conditions+band+request+maphtml+faq+bottom+'</div>'
